/**
 * scripts/bundleKatex.js
 *
 * Run from your PROJECT ROOT:
 *   node scripts/bundleKatex.js
 *
 * Writes katexAssets.js into screens/QuestionScreen/
 */

const fs   = require('fs');
const path = require('path');

// Always resolve from the project root (where node_modules lives)
// __dirname = scripts/   →   projectRoot = one level up
const projectRoot = path.resolve(__dirname, '..');

// ── Find katex in node_modules ─────────────────────────────────────────────
const possibleKatexDirs = [
  path.join(projectRoot, 'node_modules', 'katex'),
  path.join(projectRoot, 'node_modules', '.pnpm', 'katex', 'node_modules', 'katex'),
];

let katexDir = null;
for (const dir of possibleKatexDirs) {
  if (fs.existsSync(path.join(dir, 'package.json'))) {
    katexDir = dir;
    break;
  }
}

if (!katexDir) {
  // Last resort: search node_modules one level deep for a nested katex
  const nm = path.join(projectRoot, 'node_modules');
  if (fs.existsSync(nm)) {
    for (const entry of fs.readdirSync(nm)) {
      const candidate = path.join(nm, entry, 'katex', 'package.json');
      if (fs.existsSync(candidate)) {
        katexDir = path.dirname(candidate);
        break;
      }
    }
  }
}

if (!katexDir) {
  console.error('❌  Could not find katex in node_modules.');
  console.error('    Try: npm install katex   or   yarn add katex');
  console.error(`    Looked in: ${projectRoot}/node_modules/katex`);
  process.exit(1);
}

// katex.min.js and katex.min.css — some versions put them in dist/
const jsPath      = path.join(katexDir, 'katex.min.js');
const cssPath     = path.join(katexDir, 'katex.min.css');
const jsPathDist  = path.join(katexDir, 'dist', 'katex.min.js');
const cssPathDist = path.join(katexDir, 'dist', 'katex.min.css');

const finalJsPath  = fs.existsSync(jsPath)  ? jsPath  : jsPathDist;
const finalCssPath = fs.existsSync(cssPath) ? cssPath : cssPathDist;

if (!fs.existsSync(finalJsPath) || !fs.existsSync(finalCssPath)) {
  console.error('❌  Found katex but could not find katex.min.js / katex.min.css');
  console.error(`    Searched in: ${katexDir}`);
  console.error(`    and:         ${katexDir}/dist/`);
  console.error('    Contents of katex folder:', fs.readdirSync(katexDir).join(', '));
  process.exit(1);
}

console.log(`✅  Found katex at: ${katexDir}`);

// ── Read files ─────────────────────────────────────────────────────────────
const katexJs  = fs.readFileSync(finalJsPath,  'utf8');
const katexCss = fs.readFileSync(finalCssPath, 'utf8');
const version  = JSON.parse(fs.readFileSync(path.join(katexDir, 'package.json'), 'utf8')).version;

// Escape backticks and ${} so they don't break the template literal
const escape = (s) => s.replace(/\\/g, '\\\\').replace(/`/g, '\\`').replace(/\$\{/g, '\\${');

const output = `// AUTO-GENERATED by scripts/bundleKatex.js — do not edit manually.
// Regenerate with: node scripts/bundleKatex.js
// KaTeX version: ${version}

export const KATEX_JS = \`${escape(katexJs)}\`;

export const KATEX_CSS = \`${escape(katexCss)}\`;
`;

// ── Write output ───────────────────────────────────────────────────────────
const outDir  = path.join(projectRoot, 'screens', 'QuestionScreen');
const outPath = path.join(outDir, 'katexAssets.js');

if (!fs.existsSync(outDir)) {
  console.error(`❌  Output directory does not exist: ${outDir}`);
  console.error('    Make sure screens/QuestionScreen/ exists first.');
  process.exit(1);
}

fs.writeFileSync(outPath, output, 'utf8');

const sizeMb = (output.length / 1024 / 1024).toFixed(2);
console.log(`✅  katexAssets.js written to: ${outPath}`);
console.log(`    File size: ${sizeMb} MB`);
console.log(`    Commit this file — it never changes unless you upgrade katex.`);